class Solution {
public:
    bool checkValidCuts(int n, vector<vector<int>>& rectangles) {
        return canCut(rectangles, 0) || canCut(rectangles, 1);
    }
private:
    bool canCut(vector<vector<int>>& rectangles, int dim) {
        int m = rectangles.size();
        vector<pair<int,int>> intervals(m);
        for (int i = 0; i < m; i++) {
            intervals[i] = {rectangles[i][dim], rectangles[i][dim + 2]};
        }
        sort(intervals.begin(), intervals.end());
        int groups = 0;
        int maxEnd = -1;
        for (auto& [s, e] : intervals) {
            if (s >= maxEnd) groups++;
            maxEnd = max(maxEnd, e);
        }
        return groups >= 3;
    }
};
